const CACHE='cognitive-care-ner-v0.9.12';
const APP_SHELL=['./','./index.html','./config.js?v=0.9.12','./styles.css?v=0.9.12','./avatar.css?v=0.9.12','./phase1.css?v=0.9.12','./phase2.css?v=0.9.12','./phase3.css?v=0.9.12','./phase4.css?v=0.9.12','./multilingual.css?v=0.9.12','./sequence-game.css?v=0.9.12','./sorting-game.css?v=0.9.12','./category-game.css?v=0.9.12','./pattern-game.css?v=0.9.12','./spot-difference-game.css?v=0.9.12','./routine-game.css?v=0.9.12','./multilingual.js?v=0.9.12','./regional-language-runtime.js?v=0.9.12','./regional-language-feedback.js?v=0.9.12','./adaptive-engine.js?v=0.9.12','./game-controls.js?v=0.9.12','./routine-game.js?v=0.9.12','./notification-bridge.js?v=0.9.12','./security-center.js?v=0.9.12','./usability-validation.js?v=0.9.12','./production-hardening.js?v=0.9.12','./data-bridge.js?v=0.9.12','./manifest.webmanifest'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(APP_SHELL)).catch(()=>{}));self.skipWaiting()});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const u=new URL(e.request.url);if(u.origin!==self.location.origin)return;const asset=u.pathname.endsWith('.html')||u.pathname.endsWith('.js')||u.pathname.endsWith('.css')||u.pathname==='/'||u.pathname.endsWith('.webmanifest');if(asset){e.respondWith(fetch(e.request,{cache:'no-store'}).then(r=>{if(r?.ok){const c=r.clone();caches.open(CACHE).then(x=>x.put(e.request,c)).catch(()=>{})}return r}).catch(()=>caches.match(e.request).then(x=>x||caches.match('./index.html'))));return}e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request).then(r=>{const cp=r.clone();caches.open(CACHE).then(x=>x.put(e.request,cp)).catch(()=>{});return r}).catch(()=>caches.match('./index.html'))))});
